import sys
import math

def extended_gcd(a, b):
    if b == 0:
        return a, 1, 0
    gcd, x1, y1 = extended_gcd(b, a % b)
    x = y1
    y = x1 - (a // b) * y1
    return gcd, x, y

def solve():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split(',')
        if len(parts) != 3:
            continue
        a = int(parts[0].split('=')[1])
        b = int(parts[1].split('=')[1])
        c = int(parts[2].split('=')[1])

        gcd = math.gcd(a, b)
        if c % gcd != 0:
            print("-1")
            continue

        gcd, x0, y0 = extended_gcd(a, b)
        x0 = x0 * (c // gcd)
        y0 = y0 * (c // gcd)

        a_div = a // gcd
        b_div = b // gcd

        t_min = (-x0 + b_div - 1) // b_div if b_div > 0 else (-x0) // b_div
        t_max = y0 // a_div if a_div > 0 else y0 // a_div

        if t_min > t_max:
            print("-1")
            continue

        best_sum = float('inf')
        best_x, best_y = None, None

        if a_div == 0 and b_div == 0:
            pass
        elif a_div == 0:
            if y0 >= 0:
                sum_val = x0 + y0
                if sum_val < best_sum:
                    best_sum = sum_val
                    best_x, best_y = x0, y0
        elif b_div == 0:
            if x0 >= 0:
                sum_val = x0 + y0
                if sum_val < best_sum:
                    best_sum = sum_val
                    best_x, best_y = x0, y0
        else:
            candidates = []

            x1 = x0 + t_max * b_div
            y1 = y0 - t_max * a_div
            if x1 >= 0 and y1 >= 0:
                candidates.append((x1 + y1, x1, y1))

            x2 = x0 + t_min * b_div
            y2 = y0 - t_min * a_div
            if x2 >= 0 and y2 >= 0:
                candidates.append((x2 + y2, x2, y2))

            if a_div > 0:
                t_floor = y0 // a_div
                t_floor = min(t_floor, t_max)
                t_floor = max(t_floor, t_min)
                if t_floor <= t_max and t_floor >= t_min:
                    x3 = x0 + t_floor * b_div
                    y3 = y0 - t_floor * a_div
                    if x3 >= 0 and y3 >= 0:
                        candidates.append((x3 + y3, x3, y3))

            if b_div > 0:
                t_ceil = (-x0 + b_div - 1) // b_div
                t_ceil = max(t_ceil, t_min)
                t_ceil = min(t_ceil, t_max)
                if t_ceil >= t_min and t_ceil <= t_max:
                    x4 = x0 + t_ceil * b_div
                    y4 = y0 - t_ceil * a_div
                    if x4 >= 0 and y4 >= 0:
                        candidates.append((x4 + y4, x4, y4))

            if candidates:
                candidates.sort()
                best_sum, best_x, best_y = candidates[0]

        if best_x is None or best_y is None or best_x < 0 or best_y < 0:
            print("-1")
        else:
            print(f"{best_x} {best_y}")

if __name__ == "__main__":
    solve()
